'use client';
import { useCallback, useEffect, useId, useRef, useState, type FocusEvent, type KeyboardEvent, type PointerEvent } from 'react';
import { useStudioMotion } from '../../motion';
import { StudioCanvas } from '../../three';
import type { EffectProps } from '../../types';
import { FlowLines } from './fallback';
import { Scene, type Influence, type Look } from './scene';
import styles from './styles.module.css';

type Params = { count: number; intensity: number; flow: number; size: number; mode: 'Repel' | 'Attract' };

function useThemeVersion(): number {
  const [v, setV] = useState(0);
  useEffect(() => {
    const bump = () => setV((n) => n + 1);
    const mo = new MutationObserver(bump);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme', 'class', 'style'] });
    const mq = window.matchMedia?.('(prefers-color-scheme: dark)');
    mq?.addEventListener('change', bump);
    return () => { mo.disconnect(); mq?.removeEventListener('change', bump); };
  }, []);
  return v;
}

/** Relative luminance of a CSS colour via a 1×1 canvas (handles hex, rgb() and named colours). */
function luminance(css: string): number {
  const g = document.createElement('canvas').getContext('2d');
  if (!g) return 1;
  g.fillStyle = '#fff'; g.fillStyle = css; g.fillRect(0, 0, 1, 1);
  const [r, gr, b] = g.getImageData(0, 0, 1, 1).data;
  const lin = (c: number) => { const s = c / 255; return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; };
  return 0.2126 * lin(r) + 0.7152 * lin(gr) + 0.0722 * lin(b);
}

export default function ParticleFieldGpu({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const hintId = useId();
  const field = useRef<HTMLDivElement>(null);
  const influence = useRef<Influence>({ x: 0, y: 0, active: false });
  const kick = useRef<(() => void) | null>(null);
  const [paused, setPaused] = useState(false);
  const [drawn, setDrawn] = useState<number | null>(null);
  const [look, setLook] = useState<Look>({ ink: '#11110f', accent: '#bf2f09', dark: false });
  const theme = useThemeVersion();
  const running = !paused && !reduced;
  const interactive = !reduced;

  useEffect(() => {
    const el = field.current;
    if (!el) return;
    const cs = getComputedStyle(el);
    const v = (n: string, f: string) => cs.getPropertyValue(n).trim() || f;
    setLook({ ink: v('--s3-ink', '#11110f'), accent: v('--s3-signal', '#bf2f09'), dark: luminance(v('--s3-surface', '#fbf9f4')) < 0.2 });
  }, [theme]);

  const point = (e: PointerEvent<HTMLDivElement>) => {
    if (!interactive) return;
    const r = e.currentTarget.getBoundingClientRect();
    influence.current = { x: ((e.clientX - r.left) / r.width) * 2 - 1, y: 1 - ((e.clientY - r.top) / r.height) * 2, active: true };
    kick.current?.();
  };
  const leave = () => { influence.current = { ...influence.current, active: false }; kick.current?.(); };
  const onFocus = (e: FocusEvent<HTMLDivElement>) => {
    if (!interactive || !e.currentTarget.matches(':focus-visible')) return;
    influence.current = { x: 0, y: 0, active: true };
    kick.current?.();
  };
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (!interactive) return;
    const step = e.shiftKey ? 0.3 : 0.1;
    const c = influence.current;
    const move: Record<string, [number, number]> = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, step], ArrowDown: [0, -step] };
    if (move[e.key]) {
      influence.current = { x: Math.max(-1, Math.min(1, c.x + move[e.key][0])), y: Math.max(-1, Math.min(1, c.y + move[e.key][1])), active: true };
    } else if (e.key === 'Escape') influence.current = { ...c, active: false };
    else return;
    e.preventDefault();
    kick.current?.();
  };
  const onCount = useCallback((n: number) => setDrawn(n), []);

  return (
    <div className={styles.root}>
      <div
        ref={field}
        className={styles.field}
        tabIndex={interactive ? 0 : undefined}
        role={interactive ? 'application' : undefined}
        aria-label={interactive ? 'Particle flow field' : undefined}
        aria-describedby={interactive ? hintId : undefined}
        aria-keyshortcuts={interactive ? 'ArrowLeft ArrowRight ArrowUp ArrowDown Escape' : undefined}
        onPointerMove={point}
        onPointerDown={point}
        onPointerLeave={leave}
        onFocus={onFocus}
        onBlur={leave}
        onKeyDown={onKeyDown}
      >
        <StudioCanvas
          label="Particle flow field"
          description="Thousands of fine particles drift from left to right along a swirling, braided flow, like ink in slow water. The pointer pushes them aside or draws them in."
          frameloop={running ? 'always' : 'demand'}
          camera={{ fov: 50, near: 0.1, far: 20, position: [0, 0, 5] }}
          fallback={<FlowLines />}
        >
          <Scene
            count={params.count}
            intensity={params.intensity}
            flow={params.flow}
            size={params.size}
            repel={params.mode !== 'Attract'}
            running={running}
            interactive={interactive}
            look={look}
            influence={influence}
            kick={kick}
            onCount={onCount}
          />
        </StudioCanvas>
      </div>
      <div className={styles.bar}>
        {reduced ? null : (
          <button type="button" className={styles.button} aria-pressed={paused} onClick={() => setPaused((p) => !p)}>
            <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">{paused ? <path d="M5 3.5v9l7.5-4.5z" /> : <path d="M5 3.5v9M11 3.5v9" />}</svg>
            {paused ? 'Play' : 'Pause'}
          </button>
        )}
        <p id={hintId} className={styles.hint}>
          {reduced
            ? 'Motion is reduced, so the field is a still frame.'
            : `Move the pointer through the field to ${params.mode === 'Attract' ? 'draw particles in' : 'push particles aside'}. Keyboard: focus the field, arrows move the influence, Esc releases it.`}
        </p>
        <p className={styles.count}>{drawn === null ? 'Static drawing' : `${drawn.toLocaleString('en-US')} particles`}</p>
      </div>
    </div>
  );
}

'use client';
/** No-WebGL fallback: streamlines of the very same flow field, integrated in JS and drawn once as SVG paths. */
import { useMemo } from 'react';
import { velocity } from './flow';

const W = 600, H = 360, S = H / 4.66; // the WebGL view is ~4.66 world units tall

export function FlowLines() {
  const paths = useMemo(() => {
    const out: { d: string; accent: boolean }[] = [];
    let k = 0;
    for (let gy = -2.2; gy <= 2.2; gy += 0.3) {
      for (let gx = -4.6; gx <= 3.2; gx += 0.95) {
        let x = gx + ((k * 0.37) % 0.4), y = gy + ((k * 0.21) % 0.2);
        let d = `M${(W / 2 + x * S).toFixed(1)} ${(H / 2 - y * S).toFixed(1)}`;
        for (let i = 0; i < 26; i++) {
          const [vx, vy] = velocity(x * 0.8, y * 0.8, 7.5 * 0.12);
          x += vx * 0.07; y += vy * 0.07;
          d += `L${(W / 2 + x * S).toFixed(1)} ${(H / 2 - y * S).toFixed(1)}`;
        }
        out.push({ d, accent: k % 11 === 0 });
        k++;
      }
    }
    return out;
  }, []);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="xMidYMid slice" role="img" aria-label="Still drawing of the flow field: fine streamlines drifting left to right, braiding into slow eddies." style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }}>
      {paths.map((p, i) => (
        <path key={i} d={p.d} fill="none" strokeWidth={p.accent ? 1.4 : 0.9} strokeLinecap="round" style={{ stroke: p.accent ? 'var(--s3-signal, #bf2f09)' : 'var(--s3-ink-muted, #5c5a52)' }} />
      ))}
    </svg>
  );
}

/**
 * The flow field, shared by the vertex shader (GLSL string below) and the SVG fallback (JS): the curl of a scalar
 * stream function ψ(x, y, t), so the 2D velocity v = (∂ψ/∂y, −∂ψ/∂x) is divergence-free — particles swirl and
 * braid without bunching up or thinning out — plus a gentle drift to the right.
 */
export const DRIFT = 0.42;

export function velocity(x: number, y: number, t: number): [number, number] {
  const a = 0.9 * x + 0.25 * t, b = 1.1 * y - 0.2 * t, c = 1.7 * x - 1.3 * y + 0.35 * t, e = 2.6 * x + 2.1 * y - 0.15 * t;
  const dPsiDx = 0.9 * Math.cos(a) * Math.cos(b) + 0.935 * Math.cos(c) - 0.78 * Math.sin(e);
  const dPsiDy = -1.1 * Math.sin(a) * Math.sin(b) - 0.715 * Math.cos(c) - 0.63 * Math.sin(e);
  return [dPsiDy + DRIFT, -dPsiDx];
}

export const flowGlsl = /* glsl */ `
vec2 flow(vec2 p, float t) {
  float a = 0.9 * p.x + 0.25 * t, b = 1.1 * p.y - 0.2 * t, c = 1.7 * p.x - 1.3 * p.y + 0.35 * t, e = 2.6 * p.x + 2.1 * p.y - 0.15 * t;
  float dx = 0.9 * cos(a) * cos(b) + 0.935 * cos(c) - 0.78 * sin(e);
  float dy = -1.1 * sin(a) * sin(b) - 0.715 * cos(c) - 0.63 * sin(e);
  return vec2(dy + ${DRIFT.toFixed(2)}, -dx);
}`;

'use client';
import { useFrame, useThree } from '@react-three/fiber';
import { useEffect, useMemo, useRef, type RefObject } from 'react';
import { AdditiveBlending, BufferAttribute, BufferGeometry, Color, NormalBlending, ShaderMaterial, Vector2 } from 'three';
import { useQuality } from '../../three';
import { fragmentShader, vertexShader } from './shader';

export interface Influence { x: number; y: number; active: boolean } // NDC (−1…1)
export interface Look { ink: string; accent: string; dark: boolean }

export interface SceneProps {
  count: number;
  intensity: number;
  flow: number;
  size: number;
  repel: boolean;
  running: boolean;
  interactive: boolean;
  look: Look;
  influence: RefObject<Influence>;
  kick: RefObject<(() => void) | null>;
  onCount: (n: number) => void;
}

/** Deterministic per-particle seeds (no Math.random: the same field on every load). */
function seeds(n: number): { pos: Float32Array; seed: Float32Array } {
  let s = 0x9e3779b9;
  const rnd = () => { s ^= s << 13; s ^= s >>> 17; s ^= s << 5; return ((s >>> 0) % 1_000_000) / 1_000_000; };
  const pos = new Float32Array(n * 3), seed = new Float32Array(n * 4);
  for (let i = 0; i < n; i++) {
    pos[i * 3] = rnd() * 2 - 1; pos[i * 3 + 1] = rnd() * 2 - 1; pos[i * 3 + 2] = (rnd() - 0.5) * 0.2;
    seed[i * 4] = rnd(); seed[i * 4 + 1] = rnd(); seed[i * 4 + 2] = rnd(); seed[i * 4 + 3] = rnd();
  }
  return { pos, seed };
}

export function Scene({ count, intensity, flow, size, repel, running, interactive, look, influence, kick, onCount }: SceneProps) {
  const gl = useThree((s) => s.gl);
  const viewport = useThree((s) => s.viewport);
  const invalidate = useThree((s) => s.invalidate);
  const { density } = useQuality();
  const n = Math.max(500, Math.round(count * density));
  const state = useRef({ time: 7.5, push: 0 });

  const geometry = useMemo(() => {
    const { pos, seed } = seeds(n);
    const g = new BufferGeometry();
    g.setAttribute('position', new BufferAttribute(pos, 3));
    g.setAttribute('aSeed', new BufferAttribute(seed, 4));
    return g;
  }, [n]);
  useEffect(() => () => geometry.dispose(), [geometry]);
  useEffect(() => { onCount(n); }, [n, onCount]);

  const material = useMemo(() => new ShaderMaterial({
    vertexShader, fragmentShader, transparent: true, depthWrite: false, depthTest: false,
    uniforms: {
      uTime: { value: 7.5 }, uFlow: { value: 1 }, uSize: { value: 2 }, uPixelRatio: { value: 1 }, uIntensity: { value: 0.8 },
      uPointerStrength: { value: 0 }, uFieldScale: { value: 0.8 }, uBounds: { value: new Vector2(1, 1) }, uPointer: { value: new Vector2() },
      uColor: { value: new Color() }, uAccent: { value: new Color() },
    },
  }), []);
  useEffect(() => () => material.dispose(), [material]);

  useEffect(() => { kick.current = invalidate; return () => { kick.current = null; }; }, [kick, invalidate]);
  useEffect(() => {
    const u = material.uniforms;
    u.uFlow.value = flow; u.uSize.value = size; u.uIntensity.value = intensity * (look.dark ? 0.75 : 0.62);
    u.uColor.value.set(look.ink); u.uAccent.value.set(look.accent);
    material.blending = look.dark ? AdditiveBlending : NormalBlending;
    material.needsUpdate = true;
    invalidate();
  }, [material, flow, size, intensity, look, invalidate]);
  useEffect(() => {
    material.uniforms.uBounds.value.set(viewport.width / 2, viewport.height / 2);
    material.uniforms.uPixelRatio.value = gl.getPixelRatio();
    invalidate();
  }, [material, viewport.width, viewport.height, gl, invalidate]);

  useFrame((_, rawDt) => {
    const dt = Math.min(rawDt, 1 / 20);
    const s = state.current, u = material.uniforms, inf = influence.current;
    if (running) s.time += dt;
    const goal = interactive && inf?.active ? 1 : 0;
    s.push += (goal - s.push) * (1 - Math.exp(-dt * 6));
    if (Math.abs(goal - s.push) < 0.002) s.push = goal;
    if (inf) u.uPointer.value.set((inf.x * viewport.width) / 2, (inf.y * viewport.height) / 2);
    u.uTime.value = s.time;
    u.uPointerStrength.value = s.push * (repel ? 1 : -1);
    if (!running && s.push !== goal) invalidate(); // paused: keep easing the push in/out, then rest
  });

  return <points geometry={geometry} material={material} frustumCulled={false} />;
}

import { flowGlsl } from './flow';

/**
 * Every particle's position is a pure function of its seed and time: start at the seed, then integrate the flow
 * for `life` of the path in a few Euler steps. No CPU work per particle, ever — only uniforms change per frame.
 */
export const vertexShader = /* glsl */ `
uniform float uTime, uFlow, uSize, uPixelRatio, uIntensity, uPointerStrength, uFieldScale;
uniform vec2 uBounds, uPointer;
attribute vec4 aSeed; // phase, speed, size, tint
varying float vAlpha;
varying float vTint;
${flowGlsl}
void main() {
  float life = fract(aSeed.x + uTime * uFlow * (0.05 + 0.05 * aSeed.y));
  vec2 p = position.xy * uBounds * 1.25;
  float h = life * 2.6 / 7.0;
  for (int i = 0; i < 7; i++) p += flow(p * uFieldScale, uTime * 0.12) * h;
  vec2 d = p - uPointer;
  float r2 = dot(d, d);
  p += (r2 > 1e-6 ? d * inversesqrt(r2) : vec2(0.0)) * uPointerStrength * exp(-r2 * 2.2) * 0.55;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(p, position.z, 1.0);
  gl_PointSize = uSize * uPixelRatio * (0.55 + aSeed.z * 0.9);
  vAlpha = smoothstep(0.0, 0.14, life) * (1.0 - smoothstep(0.72, 1.0, life)) * uIntensity;
  vTint = aSeed.w;
}`;

export const fragmentShader = /* glsl */ `
precision highp float;
uniform vec3 uColor, uAccent;
varying float vAlpha;
varying float vTint;
void main() {
  float r = length(gl_PointCoord - 0.5);
  float a = smoothstep(0.5, 0.1, r) * vAlpha;
  if (a < 0.003) discard;
  vec3 c = mix(uColor, uAccent, step(0.9, vTint));
  // Blending is chosen by the theme: additive light on dark stages, ordinary alpha (ink builds up like graphite) on light.
  gl_FragColor = vec4(c, a);
  #include <colorspace_fragment>
}`;

.root {
  container-type: inline-size;
  width: 100%;
  align-self: stretch;
  display: grid;
  grid-template-rows: 1fr auto;
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  color: var(--s3-ink, #11110f);
}
.field {
  position: relative;
  min-height: clamp(300px, 56cqi, 480px);
  overflow: hidden;
  cursor: crosshair;
  touch-action: pan-y;
  outline: none;
}
.field:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: -4px; }
.field > [data-studio3-canvas] { position: absolute !important; inset: 0; }

.bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 18px;
  padding: 12px clamp(12px, 3cqi, 24px);
  border-top: 1px solid var(--s3-line, #11110f24);
}
.button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 0 18px 0 14px;
  border: 1px solid var(--s3-line-strong, #11110f);
  border-radius: 999px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
}
.button svg { width: 16px; height: 16px; fill: currentColor; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.button:hover { background: var(--s3-ink, #11110f); color: var(--s3-surface, #fbf9f4); }
.button:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.hint { flex: 1 1 18rem; margin: 0; font-size: 0.8125rem; line-height: 1.45; color: var(--s3-ink-muted, #5c5a52); }
.count {
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: var(--s3-ink-muted, #5c5a52);
}
